def semver_sort(versions):
    def parse_key(v):
        main = v
        build = None
        if '+' in main:
            main, build = main.split('+', 1)
        prerelease = None
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core = main
        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])
        if prerelease is not None:
            has_pre = 0
            idents = prerelease.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
        else:
            has_pre = 1
            pre_key = []
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse_key)

